using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollmentRequests = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and communication." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and their impact on society." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms and life processes." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Bio = "Dr. Chen has over 15 years of experience in software engineering and distributed systems. She holds a PhD from MIT and has published extensively on cloud computing architectures.", Email = "s.chen@university.edu", Office = "Science Hall 301" },
            new() { Id = 2, Name = "Dr. James Morton", Title = "Associate Professor", Bio = "Dr. Morton specializes in linear algebra and topology. He received his PhD from Stanford and has been teaching for 10 years.", Email = "j.morton@university.edu", Office = "Math Building 205" },
            new() { Id = 3, Name = "Prof. Elena Rodriguez", Title = "Professor", Bio = "Prof. Rodriguez is an award-winning author and literary critic with expertise in modern American literature and creative writing.", Email = "e.rodriguez@university.edu", Office = "Humanities 412" },
            new() { Id = 4, Name = "Dr. Michael Park", Title = "Assistant Professor", Bio = "Dr. Park researches quantum mechanics and particle physics. He completed postdoctoral work at CERN before joining the faculty.", Email = "m.park@university.edu", Office = "Physics Lab 108" },
            new() { Id = 5, Name = "Dr. Amanda Foster", Title = "Professor", Bio = "Dr. Foster is a historian specializing in medieval European history and the Renaissance period. She has authored three acclaimed books.", Email = "a.foster@university.edu", Office = "Liberal Arts 220" },
            new() { Id = 6, Name = "Dr. Robert Kim", Title = "Associate Professor", Bio = "Dr. Kim researches molecular biology and genetics. He leads the university's genomics lab and mentors graduate students.", Email = "r.kim@university.edu", Office = "Life Sciences 315" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Computer Science", Description = "An introductory course covering fundamental concepts of programming, data structures, and algorithmic thinking. Students will learn Python and develop problem-solving skills.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 101", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS 301", Title = "Data Structures and Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Covers algorithm design techniques and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 204", DepartmentId = 1, InstructorId = 1, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning algorithms including supervised and unsupervised learning, neural networks, and practical applications.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Science Hall 310", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, and eigenvalues. Essential for students in mathematics, physics, and computer science.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 72 },
            new() { Id = 5, Code = "MATH 305", Title = "Differential Equations", Description = "First and second order differential equations, systems of equations, Laplace transforms, and numerical methods.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 203", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 38 },
            new() { Id = 6, Code = "ENG 102", Title = "Composition and Rhetoric", Description = "Development of writing skills with emphasis on argumentation, research methods, and clear communication.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Humanities 201", DepartmentId = 3, InstructorId = 3, IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
            new() { Id = 7, Code = "ENG 340", Title = "American Literature: 1900–Present", Description = "Survey of American literary works from the twentieth century to the present, exploring themes of identity, culture, and social change.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Location = "Humanities 305", DepartmentId = 3, InstructorId = 3, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 30 },
            new() { Id = 8, Code = "PHYS 201", Title = "Classical Mechanics", Description = "Newtonian mechanics, conservation laws, oscillations, and an introduction to Lagrangian mechanics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Physics Lab 101", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 48 },
            new() { Id = 9, Code = "PHYS 410", Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave functions, Schrödinger equation, and quantum measurement. Prerequisites: PHYS 201, MATH 305.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Physics Lab 205", DepartmentId = 4, InstructorId = 4, IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 25 },
            new() { Id = 10, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, cultures, and events from antiquity through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Liberal Arts 101", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 85 },
            new() { Id = 11, Code = "HIST 320", Title = "The Renaissance and Reformation", Description = "In-depth study of European cultural, religious, and political transformations from the 14th to 17th centuries.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", Location = "Liberal Arts 215", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
            new() { Id = 12, Code = "BIO 101", Title = "General Biology", Description = "Introduction to biological principles including cell biology, genetics, evolution, and ecology.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Location = "Life Sciences 101", DepartmentId = 6, InstructorId = 6, IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
            new() { Id = 13, Code = "BIO 330", Title = "Molecular Biology", Description = "Study of molecular mechanisms of gene expression, DNA replication, and protein synthesis.", Credits = 4, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Life Sciences 210", DepartmentId = 6, InstructorId = 6, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 35 }
        };

        // Link navigation properties
        foreach (var course in _courses)
        {
            course.Department = _departments.First(d => d.Id == course.DepartmentId);
            course.Instructor = _instructors.First(i => i.Id == course.InstructorId);
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null, int? credits = null)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (credits.HasValue && credits.Value > 0)
            query = query.Where(c => c.Credits == credits.Value);

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        request.SubmittedAt = DateTime.UtcNow;
        _enrollmentRequests.Add(request);
    }
}

