    {
        <div class="list-group">
            @foreach (var course in _courses)
            {
                <a href="courses/@course.Id" class="list-group-item list-group-item-action">
                    <div class="d-flex w-100 justify-content-between">
                        <h5 class="mb-1">@course.Code — @course.Title</h5>
                        <small>@course.Credits credits</small>
                    </div>
                    <p class="mb-1">@course.Schedule &middot; @course.Instructor.Name</p>
                    <small>@course.CurrentEnrollment / @course.MaxEnrollment enrolled</small>
                </a>
            }
        </div>
    }
    else
    {
        <p>No courses available for this department.</p>
    }
}

@code {
    [Parameter] public int Id { get; set; }

    private Department? _department;
    private List<Course> _courses = new();

    protected override void OnInitialized()
    {
        _department = CatalogService.GetDepartment(Id);
        if (_department is not null)
            _courses = CatalogService.GetCoursesByDepartment(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request below. You will receive confirmation via your university email.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted Successfully!</h4>
        <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been submitted. You will receive a confirmation email shortly.</p>
        <a href="enroll" class="btn btn-outline-success">Submit Another Request</a>
    </div>
}
else
{
    <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                   value="@Model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                   value="@Model.StudentId" required placeholder="e.g., STU-12345" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">— Select a course —</option>
                @foreach (var course in _courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.Code — @course.Title (@course.Credits cr)
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<Course> _courses = new();
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";

        CatalogService.SubmitEnrollmentRequest(new EnrollmentRequest
        {
            StudentName = Model.StudentName,
            StudentId = Model.StudentId,
            CourseId = Model.CourseId
        });

        _submitted = true;
    }
}

