    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (CourseId.HasValue && Model.CourseId == 0)
            Model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourse(Model.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code} — {course.Title}" : "Unknown Course";

        CatalogService.SubmitEnrollmentRequest(new EnrollmentRequest
        {
            StudentName = Model.StudentName,
            StudentId = Model.StudentId,
            CourseId = Model.CourseId
        });

        _submitted = true;
    }
}
